Library version: master @ cd42b99
Platform: Windows 10 64-bit
Compiler: MSVC 2019 64-bit

When importing any .glb files generated by the "glb" exporter, the GLTF 1.0 importer generates the following assertion failure in debug builds (in release builds, it just crashes):

    ai_assert failure in C:\Users\jason\Packages\assimp-git\code\AssetLib\glTF\glTFImporter.cpp(452): validRes

This happened for all models tested, including:
- An official GLTF 1.0 binary reference model from [here](https://github.com/KhronosGroup/glTF-Sample-Models/tree/master/1.0/Box/glTF-Binary), imported and then re-exported.
- Manually generated aiScenes exported with the "glb" exporter.
- A [number of models](https://github.com/JC3/ModelSplit/tree/assimp-master-cd42b99/specific_tests/models) that were imported, exported with the "glb" exporter, then re-imported from the exported glb

Here is one of the test programs I used (this will import a file, export it using the glb exporter, then attempt to re-import that exported file):

```
#include <cstdio>
#include <assimp/Importer.hpp>
#include <assimp/Exporter.hpp>
#include <assimp/version.h>

using namespace std;

int main (int argc, char **argv) {

    const char *modelfile = (argc > 1 ? argv[1] : nullptr);
    if (!modelfile) {
        fprintf(stderr, "no model file specified\n");
        return 1;
    }

    printf("assimp %d.%d.%d (%s @ %08x)\n", aiGetVersionMajor(), aiGetVersionMinor(),
           aiGetVersionPatch(), aiGetBranchName(), aiGetVersionRevision());

    printf("importing %s...\n", modelfile);
    Assimp::Importer importer;
    const aiScene *scene = importer.ReadFile(modelfile, 0);
    if (!scene) {
        fprintf(stderr, "error: %s\n", importer.GetErrorString());
        return 1;
    }

    printf("exporting scene.glb...\n");
    Assimp::Exporter exporter;
    if (exporter.Export(scene, "glb", "scene.glb") != AI_SUCCESS) {
        fprintf(stderr, "error: %s\n", exporter.GetErrorString());
        return 1;
    }

    printf("importing scene.glb...\n");
    Assimp::Importer reimporter;
    scene = reimporter.ReadFile("scene.glb", 0);
    if (!scene) {
        fprintf(stderr, "error: %s\n", reimporter.GetErrorString());
        return 1;
    }

    printf("finished.\n");
    return 0;

}
```

Example output of that program:

```
assimp 5.0.1 (master @ cd42b995)
importing ..\models\torus.dae...
exporting scene.glb...
importing scene.glb...
ai_assert failure in C:\Users\jason\Packages\assimp-git\code\AssetLib\glTF\glTFImporter.cpp(452): validRes
```

One example of a .glb file (produced by the "glb" exporter) that causes an assertion failure on import is attached: [scene.zip](https://github.com/assimp/assimp/files/6340778/scene.zip)
